        "code": "def audit_set_cookie(header):\n    \"\"\"Return the list of security problems found in one Set-Cookie header.\"\"\"\n    parts = [p.strip() for p in header.split(\";\")]\n    name = parts[0].split(\"=\", 1)[0]\n    # Attribute names are case-insensitive\n    attrs = {}\n    for part in parts[1:]:\n        key, _, value = part.partition(\"=\")\n        attrs[key.strip().lower()] = value.strip()\n\n    problems = []\n    if \"httponly\" not in attrs:\n        problems.append(\"missing HttpOnly (JavaScript can read the cookie)\")\n    if \"secure\" not in attrs:\n        problems.append(\"missing Secure (sent over plain HTTP)\")\n    if attrs.get(\"samesite\", \"\").lower() not in (\"lax\", \"strict\"):\n        problems.append(\"SameSite must be Lax or Strict\")\n    if name.startswith(\"__Host-\"):\n        # Browsers reject a __Host- cookie that breaks one of these rules\n        if \"secure\" not in attrs or attrs.get(\"path\") != \"/\" or \"domain\" in attrs:\n            problems.append(\"__Host- requires Secure, Path=/ and no Domain\")\n    else:\n        problems.append(\"name should use the __Host- prefix\")\n    return problems\n\n\nheaders = [\n    \"sid=abc123; Path=/; Domain=example.com\",\n    \"__Host-sid=q9Zt0cXw; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=1800\",\n]\n\nfor header in headers:\n    print(header)\n    problems = audit_set_cookie(header)\n    if not problems:\n        print(\"  OK\")\n    for problem in problems:\n        print(\"  -\", problem)\n",
