        "code": "import base64\nimport hashlib\nimport hmac\nimport json\n\nSECRET = b\"demo-secret-of-at-least-32-bytes-long!\"\n\n\ndef b64url(data):\n    # JWT uses base64url WITHOUT the trailing \"=\" padding\n    return base64.urlsafe_b64encode(data).rstrip(b\"=\").decode()\n\n\ndef b64url_decode(text):\n    # Put the padding back before decoding\n    return base64.urlsafe_b64decode(text + \"=\" * (-len(text) % 4))\n\n\n# Step 1: header and payload are plain JSON\nheader = {\"alg\": \"HS256\", \"typ\": \"JWT\"}\npayload = {\n    \"iss\": \"https://auth.example.com\",\n    \"aud\": \"orders-api\",\n    \"sub\": \"user-42\",\n    \"role\": \"user\",\n    \"iat\": 1767225600,  # fixed timestamps so the output is reproducible\n    \"exp\": 1767226500,  # iat + 15 minutes\n}\n\n# Step 2: each part is base64url-encoded (encoded, NOT encrypted)\nh = b64url(json.dumps(header, separators=(\",\", \":\")).encode())\np = b64url(json.dumps(payload, separators=(\",\", \":\")).encode())\n\n# Step 3: the signature covers \"header.payload\"\nsignature = hmac.new(SECRET, f\"{h}.{p}\".encode(), hashlib.sha256).digest()\ntoken = f\"{h}.{p}.{b64url(signature)}\"\n\nprint(\"Token:\")\nprint(token)\nprint()\n\n# Anyone can read the content without the secret\npart_h, part_p, part_s = token.split(\".\")\nprint(\"Header   :\", b64url_decode(part_h).decode())\nprint(\"Payload  :\", b64url_decode(part_p).decode())\nprint(\"Signature:\", len(b64url_decode(part_s)), \"bytes (HMAC-SHA256)\")\n",
