        "code": "import base64\nimport hashlib\nimport hmac\nimport json\n\nSECRET = b\"demo-secret-of-at-least-32-bytes-long!\"\nNOW = 1767229200  # fixed \"current time\" for the demo (real code uses time.time())\n\n\ndef b64url(data):\n    return base64.urlsafe_b64encode(data).rstrip(b\"=\").decode()\n\n\ndef b64url_decode(text):\n    return base64.urlsafe_b64decode(text + \"=\" * (-len(text) % 4))\n\n\ndef make_token(header, payload, secret=SECRET):\n    h = b64url(json.dumps(header, separators=(\",\", \":\")).encode())\n    p = b64url(json.dumps(payload, separators=(\",\", \":\")).encode())\n    if header[\"alg\"] == \"none\":\n        return f\"{h}.{p}.\"\n    sig = hmac.new(secret, f\"{h}.{p}\".encode(), hashlib.sha256).digest()\n    return f\"{h}.{p}.{b64url(sig)}\"\n\n\ndef verify_vulnerable(token):\n    h, p, s = token.split(\".\")\n    header = json.loads(b64url_decode(h))\n    # VULNERABLE 1: the algorithm is chosen by the token, i.e. by the attacker\n    if header[\"alg\"] == \"none\":\n        return json.loads(b64url_decode(p))\n    expected = b64url(hmac.new(SECRET, f\"{h}.{p}\".encode(), hashlib.sha256).digest())\n    # VULNERABLE 2: \"!=\" is not a constant-time comparison\n    if s != expected:\n        raise ValueError(\"bad signature\")\n    # VULNERABLE 3: exp, aud and iss are never checked\n    return json.loads(b64url_decode(p))\n\n\n# A legitimate token that expired one hour ago\nold = make_token(\n    {\"alg\": \"HS256\", \"typ\": \"JWT\"},\n    {\"sub\": \"user-42\", \"role\": \"user\", \"exp\": NOW - 3600},\n)\nprint(\"expired token accepted :\", verify_vulnerable(old))\n\n# The attacker writes their own payload and declares \"alg\": \"none\": no secret needed\nforged = make_token(\n    {\"alg\": \"none\", \"typ\": \"JWT\"},\n    {\"sub\": \"user-42\", \"role\": \"admin\", \"exp\": NOW + 3600},\n)\nprint(\"forged token accepted  :\", verify_vulnerable(forged))\n",
