        "file": "verify_secure.py",
        "lang": "python",
        "kind": "secure",
        "code": "import base64\nimport hashlib\nimport hmac\nimport json\n\nSECRET = b\"demo-secret-of-at-least-32-bytes-long!\"\nISSUER = \"https://auth.example.com\"\nAUDIENCE = \"orders-api\"\nNOW = 1767229200  # fixed \"current time\" for the demo (real code uses time.time())\n\n\ndef b64url(data):\n    return base64.urlsafe_b64encode(data).rstrip(b\"=\").decode()\n\n\ndef b64url_decode(text):\n    return base64.urlsafe_b64decode(text + \"=\" * (-len(text) % 4))\n\n\ndef make_token(header, payload, secret=SECRET):\n    h = b64url(json.dumps(header, separators=(\",\", \":\")).encode())\n    p = b64url(json.dumps(payload, separators=(\",\", \":\")).encode())\n    if header[\"alg\"] == \"none\":\n        return f\"{h}.{p}.\"\n    sig = hmac.new(secret, f\"{h}.{p}\".encode(), hashlib.sha256).digest()\n    return f\"{h}.{p}.{b64url(sig)}\"\n\n\ndef verify_secure(token, now=NOW):\n    try:\n        h, p, s = token.split(\".\")\n        header = json.loads(b64url_decode(h))\n        signature = b64url_decode(s)\n    except ValueError:\n        raise ValueError(\"malformed token\")\n    # FIX 1: the server decides the algorithm; the header is only compared to it\n    if header.get(\"alg\") != \"HS256\":\n        raise ValueError(\"unexpected algorithm\")\n    expected = hmac.new(SECRET, f\"{h}.{p}\".encode(), hashlib.sha256).digest()\n    # FIX 2: constant-time comparison of the raw signatures\n    if not hmac.compare_digest(signature, expected):\n        raise ValueError(\"bad signature\")\n    claims = json.loads(b64url_decode(p))\n    # FIX 3: claims are trusted only AFTER the signature, and all are required\n    if claims.get(\"exp\", 0) <= now:\n        raise ValueError(\"token expired\")\n    if claims.get(\"iss\") != ISSUER:\n        raise ValueError(\"wrong issuer\")\n    if claims.get(\"aud\") != AUDIENCE:\n        raise ValueError(\"wrong audience\")\n    return claims\n\n\ndef check(label, token):\n    try:\n        print(f\"{label:16}: accepted, role = {verify_secure(token)['role']}\")\n    except ValueError as error:\n        print(f\"{label:16}: REJECTED ({error})\")\n\n\nbase = {\"iss\": ISSUER, \"aud\": AUDIENCE, \"sub\": \"user-42\", \"role\": \"user\"}\nadmin = {**base, \"role\": \"admin\", \"exp\": NOW + 900}\nhs256 = {\"alg\": \"HS256\", \"typ\": \"JWT\"}\n\nvalid = make_token(hs256, {**base, \"exp\": NOW + 900})\ncheck(\"valid token\", valid)\n\ncheck(\"alg none\", make_token({\"alg\": \"none\", \"typ\": \"JWT\"}, admin))\n\n# Tampering: swap the payload but keep the old signature\nh, p, s = valid.split(\".\")\nforged_payload = b64url(json.dumps(admin, separators=(\",\", \":\")).encode())\ncheck(\"tampered payload\", f\"{h}.{forged_payload}.{s}\")\n\ncheck(\"expired\", make_token(hs256, {**base, \"exp\": NOW - 3600}))\ncheck(\"other audience\", make_token(hs256, {**base, \"aud\": \"billing-api\", \"exp\": NOW + 900}))\ncheck(\"guessed secret\", make_token(hs256, admin, secret=b\"secret\"))\n",
        "output": "valid token     : accepted, role = user\nalg none        : REJECTED (unexpected algorithm)\ntampered payload: REJECTED (bad signature)\nexpired         : REJECTED (token expired)\nother audience  : REJECTED (wrong audience)\nguessed secret  : REJECTED (bad signature)\n",
        "note": {
          "fr": "Cinq attaques, cinq refus. L'ordre compte : l'algorithme est comparé à une valeur fixée par le serveur, la signature est vérifiée à temps constant, et les claims ne sont lus qu'ensuite. Ce code sert à comprendre ; en production, utilisez une bibliothèque éprouvée comme dans l'exemple suivant.",
          "en": "Five attacks, five rejections. Order matters: the algorithm is compared with a value fixed by the server, the signature is verified in constant time, and the claims are only read afterwards. This code is for understanding; in production, use a proven library as in the next example."
        }
