        "kind": "secure",
        "code": "# pip install \"pyjwt[crypto]\" flask\nfrom functools import wraps\n\nimport jwt\nfrom flask import Flask, g, jsonify, request\nfrom jwt import PyJWKClient\n\nISSUER = \"https://auth.example.com\"\nAUDIENCE = \"orders-api\"\n\n# Public keys published by the issuer; the client caches them and\n# picks the right one from the \"kid\" field of the token header.\njwks_client = PyJWKClient(f\"{ISSUER}/.well-known/jwks.json\")\n\napp = Flask(__name__)\n\n\ndef verify_access_token(token):\n    signing_key = jwks_client.get_signing_key_from_jwt(token)\n    return jwt.decode(\n        token,\n        signing_key.key,\n        algorithms=[\"RS256\"],      # allow-list: blocks \"none\" and HS256 confusion\n        audience=AUDIENCE,          # the token must have been issued for THIS API\n        issuer=ISSUER,\n        options={\"require\": [\"exp\", \"iat\", \"iss\", \"aud\", \"sub\"]},\n        leeway=30,                  # tolerate 30 seconds of clock drift\n    )\n    # Never do this to \"read\" a token on the server:\n    #   jwt.decode(token, options={\"verify_signature\": False})\n\n\ndef require_token(view):\n    @wraps(view)\n    def wrapper(*args, **kwargs):\n        header = request.headers.get(\"Authorization\", \"\")\n        if not header.startswith(\"Bearer \"):\n            return jsonify(error=\"missing bearer token\"), 401\n        try:\n            g.claims = verify_access_token(header.removeprefix(\"Bearer \"))\n        except jwt.ExpiredSignatureError:\n            return jsonify(error=\"token expired\"), 401\n        except jwt.PyJWTError:\n            # Same generic answer for every other failure: no hint for the attacker\n            return jsonify(error=\"invalid token\"), 401\n        return view(*args, **kwargs)\n    return wrapper\n\n\n@app.get(\"/orders\")\n@require_token\ndef list_orders():\n    # The identity comes from the verified token, never from a request parameter\n    return jsonify(owner=g.claims[\"sub\"], orders=[])\n",
